pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint128 prevDeposit, uint128 depositAmount, address caller) public {
        // Restrict amounts to avoid overflow and keep them wide
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        uint256 prev = uint256(prevDeposit);
        uint256 amount = uint256(depositAmount);
        // Ensure the sum does not overflow uint256
        vm.assume(prev + amount > prev);

        // Perform an initial deposit to establish a known balance, if any
        if (prev > 0) {
            vm.deal(caller, prev);
            vm.prank(caller);
            c.deposit{value: prev}();
        }
        // Perform the second deposit, whose correctness we test
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();

        // After the second deposit, the caller's balance must be prev + amount
        uint256 expected = prev + amount;
        uint256 actual = c.balances(caller);
        assertTrue(actual == expected, "balance mismatch after deposit");
    }
}

